        /**
         * Opens the workflow detail page based on the provided workflow detail object.
         * @param {Object} oWorkFlowDetail 
         */
        open: function (oWorkFlowDetail) {

            var oModel = this._oWorkflowDialog.getModel("mWorkflow");
            var sRelevantFor = this._relevantFor;
            var aCreateOptionList = oModel.getProperty("/dialog/createOptions");
            var aCreateOption = JSON.parse(JSON.stringify(aCreateOptionList[sRelevantFor]));

            // TODO: CUSTATT
            if (oWorkFlowDetail && (oWorkFlowDetail.detailPage === "InspectionDetail" || oWorkFlowDetail.detailPage === "asdDetail")) {
                this.getDetails(oWorkFlowDetail);
            }
            if (Object.keys(oWorkFlowDetail).includes("showCreateButton")) {
                oModel.setProperty("/dialog/viewCreateButton", oWorkFlowDetail.showCreateButton);
            } else {
                // TODO: CUSTATT
                var bViewCreateButton = this._definitionId && this._definitionId.length > 0 ? true : false;
                oModel.setProperty("/dialog/viewCreateButton", bViewCreateButton);
            }

            if (sRelevantFor === "MSP") {
                if (oWorkFlowDetail.fundingStatus === "FUNDED") {
                    aCreateOption = aCreateOption.filter(function (oOption) {
                        return oOption.key !== "fnCreateMSPApprovalWorkflow";
                    });
                }
                if (oWorkFlowDetail.fundingStatus === "DEFERRED") {
                    aCreateOption = aCreateOption.filter(function (oOption) {
                        return oOption.key !== "fnCreateMSPDeferralWorkflow";
                    });
                }
                oModel.setProperty("/dialog/currentCreateOptions", aCreateOption);
            }

            if (Object.keys(oWorkFlowDetail).includes("allowedCreateOption")) {
                aCreateOption = aCreateOption.filter(function (oOption) {
                    return oWorkFlowDetail.allowedCreateOption.includes(oOption.key);
                });
                oModel.setProperty("/dialog/currentCreateOptions", aCreateOption);
            }

            this.onOpen();

        },

        /**
         * Retrieves and sets workflow details from the provided workflow detail object.
         * @param {Object} oWorkFlowDetail 
         */
        getDetails: function (oWorkFlowDetail) {

            var oModel = this._oWorkflowDialog.getModel("mWorkflow");
            var details = {
                "createdBy": oWorkFlowDetail.createdBy,
                "desc": oWorkFlowDetail.assessment,
                "date": oWorkFlowDetail.InspectionDate,
                "objectType": oWorkFlowDetail.objectType,
                "equipDesc": oWorkFlowDetail.equipDesc,
                "fLocDesc": oWorkFlowDetail.fLocDesc
            };

            oModel.setProperty("/detailPageWorkFlow", details);
            oModel.refresh();

        },

