        /**
         * Function to create MSP Defferal Workflow
         */
        fnCreateMSPApprovalWorkflow: function () {

            var oModel = this._oWorkflowDialog.getModel("mWorkflow");
            var oI18nModel = this.fnGetResourceBundleModel();
            var oConfig = oModel.getProperty("/config");

            oModel.setProperty("/create/mspMultilevelApprovalWorkflow", {
                "msp": oConfig.msp,
                "mspDisplayId": oConfig.mspDisplayId,
                "mspId": oConfig.mspId,
                "mspGuid": oConfig.mspId,
                "noOfLevels": 0,
                "maxLevelAllowed": 50,
                "levelsAndApprovers": [],
                "comments": "",
                "enableCreateButton": true,
                "requester": "",
                "notifyByEmail": false
            });

            if (!this._oDialogCreateMSPMultiLevelApproval) {
                Fragment.load({
                    name: "com.asint.ais.library.workflow.fragment.CreateMSPMultilevelApproval",
                    controller: this
                }).then(function (oDialog) {
                    this._oDialogCreateMSPMultiLevelApproval = oDialog;
                    if (oI18nModel) {
                        oDialog.setModel(oI18nModel, "i18n");
                    }
                    oDialog.setModel(oModel, "mWorkflow");
                    this._oDialogCreateMSPMultiLevelApproval.open();
                }.bind(this));
            } else {
                if (oI18nModel) {
                    this._oDialogCreateMSPMultiLevelApproval.setModel(oI18nModel, "i18n");
                }
                this._oDialogCreateMSPMultiLevelApproval.setModel(oModel, "mWorkflow");
                this._oDialogCreateMSPMultiLevelApproval.open();
            }

        },

        /**
         * Function to handle MSP MultiLevel level change
         * 
         */
        onCreateMSPMultiLevelApprovalLevelChange: function () {

            var oModel = this._oDialogCreateMSPMultiLevelApproval.getModel("mWorkflow");
            var oConfig = oModel.getProperty("/config");
            var iNoOfLevels = oModel.getProperty("/create/mspMultilevelApprovalWorkflow/noOfLevels");
            var aLevelsAndApprovers = oModel.getProperty("/create/mspMultilevelApprovalWorkflow/levelsAndApprovers");
            var bEnableCreateButton = true;

            if (aLevelsAndApprovers.length > iNoOfLevels) {
                aLevelsAndApprovers = aLevelsAndApprovers.slice(0, iNoOfLevels);
            }
            for (var i = 0; i < iNoOfLevels; i++) {
                if (!aLevelsAndApprovers[i]) {
                    aLevelsAndApprovers[i] = {
                        "level": "",
                        "approver": ""
                    };
                }
                if (i === iNoOfLevels - 1) {
                    aLevelsAndApprovers[i].level = oConfig && oConfig.levelText ? (oConfig.levelText["n"] || "Approver") : "Approver";
                } else {
                    aLevelsAndApprovers[i].level = oConfig && oConfig.levelText ? (oConfig.levelText[i + 1] || "Endorser") : "Endorser";
                }
                aLevelsAndApprovers[i].approver = aLevelsAndApprovers[i].approver.toLowerCase().trim();
                if (this.fnValidateEmail(aLevelsAndApprovers[i].approver) === "Error") {
                    bEnableCreateButton = false;
                }
            }
            oModel.setProperty("/create/mspMultilevelApprovalWorkflow/levelsAndApprovers", aLevelsAndApprovers);
            oModel.setProperty("/create/mspMultilevelApprovalWorkflow/enableCreateButton", iNoOfLevels === 0 ? true : bEnableCreateButton);

        },

