        /**
         * Function to handle ASD Technical Review workflow decision
         * 
         * @param {String} sAssessmentId
         */
        fnHandleRCMOnTechnicalReviewWorkflowDecision: function (sAssessmentId, sWorkflowStatus) {

            var that = this;
            var mWorkflow = this._oWorkflowDialog.getModel("mWorkflow");
            var oContext = mWorkflow.getProperty("/context");
            // var oInstanceContext = mWorkflow.getProperty("/instanceContext");
            // var oCustomData = oInstanceContext.custom;
            // var oStartEvent = oInstanceContext.startEvent;


            if (sWorkflowStatus) {
                that.fnRCMTechnicalReviewSetWorkflowData(sWorkflowStatus, sAssessmentId, function (oAssessmentHeader) {
                    var aApproralWorkflowDetail = [];
                    var oApprovalWorkflowData = {
                        "status": sWorkflowStatus,
                        "numberOfLevels": null,
                        "type": "TECHNICAL_REVIEW",
                        "currentLevel": null,
                        "requestedBy": null,
                        "requestedAt": null,
                        "approvedBy": null,
                        "approvedAt": null,
                        "detail": null,
                        "deleted": false
                    };

                    if (oAssessmentHeader && oAssessmentHeader.to_workflow && oAssessmentHeader.to_workflow.length > 0) {
                        if (oAssessmentHeader.to_workflow[0].detail) {
                            aApproralWorkflowDetail = JSON.parse(oAssessmentHeader.to_workflow[0].detail);
                        }
                        oApprovalWorkflowData.ID = oAssessmentHeader.to_workflow[0].ID;
                        // eslint-disable-next-line camelcase
                        // oApprovalWorkflowData.workflow_ID = oAssessmentHeader.workflow.approvalWorkflow.workflow_ID;
                    }

                    aApproralWorkflowDetail.push({
                        "status": sWorkflowStatus,
                        "level": null,
                        "levelText": "Reviewer",
                        "requestedBy": oApprovalWorkflowData.requestedBy,
                        "requestedAt": oApprovalWorkflowData.requestedAt,
                        "approvedBy": oContext.reviewer,
                        "approvedAt": new Date().toISOString() || null,
                        "comments": oContext.comment || oContext.comments || "",
                        "reviewers": null,
                        "icon": sWorkflowStatus === "APPROVED" ? "sap-icon://sys-enter" : "sap-icon://sys-cancel"
                    });

                    if (aApproralWorkflowDetail.length > 0) {
                        oApprovalWorkflowData.requestedBy = aApproralWorkflowDetail[0].requestedBy;
                        oApprovalWorkflowData.requestedAt = aApproralWorkflowDetail[0].requestedAt;
                        oApprovalWorkflowData.approvedBy = oContext.reviewer;
                        oApprovalWorkflowData.approvedAt = new Date().toISOString() || null;
                    }
                    
                    oApprovalWorkflowData.detail = aApproralWorkflowDetail.length ? JSON.stringify(aApproralWorkflowDetail) : null;

                    oAssessmentHeader.notifyByEmail = oContext.notifyByEmail;

                    return {
                        "_workflow": oApprovalWorkflowData
                    };
                }, function () {
                    that._fnEvent("rcmTechnicalReviewCompleteSuccess");
                }, function () {
                    that._fnEvent("rcmTechnicalReviewCompleteError");
                });
            }

        },

        /**
         * Function to update RCM Workflow
         * 
         * @param {String} sWorkflowStatus
         * @param {String} sAssessmentId
         * @param {Object} oApprovalWorkflowData
         * @param {Function} fnSuccess
         * @param {Function} fnError
         */
        fnRCMTechnicalReviewSetWorkflowData: function (sWorkflowStatus, sAssessmentId, fnGenPayload, fnSuccess, fnError) {

            var that = this;
            var oI18n = sap.ui.getCore().getLibraryResourceBundle("com.asint.ais.library");
            var mWorkflow = this._oWorkflowDialog.getModel("mWorkflow");
            // var oInstanceContext = mWorkflow.getProperty("/instanceContext");
            // var oCustomData = oInstanceContext.custom;        

            /**
             * Function to handle error
             * 
             * @param {Object} oError 
             */
            var fHandleError = function (oError) {
                var err = JSON.parse(oError.responseText);
                var errorDetail = "";

                if (err.error.message) {
                    errorDetail = err.error.message;
                }
                mWorkflow.setProperty("/dialog/isBusy", false);
                that.fnMessageShow("E", oI18n.getText("workflow.request.message.005"), errorDetail);
                if (fnError) {
                    fnError();
                }
            };
            /**
             * Function to update assessment workflow
             * 
             * @param {Object} oAssessmentHeader 
             */
            var fnHandleComplete = function (oAssessmentHeader) {
                var sEtag = oAssessmentHeader["@etag"];
                var oPayload = fnGenPayload(oAssessmentHeader);
                var oWorkflowPayload = oPayload._workflow;

                delete oPayload._workflow;

                oPayload.technicalReviewCompleted = sWorkflowStatus === "APPROVED";
                that.rcmDataSource.updateRcmAssessmentDetails(sAssessmentId, oPayload, function () {
                    if(oWorkflowPayload.ID) {
                        that.workBenchDataSource.updateWorkflow([oWorkflowPayload], function () {
                            mWorkflow.setProperty("/dialog/isBusy", false);

                            if (oAssessmentHeader.notifyByEmail) {
                                that.fnHandleSendEmail("RCM", "TECHNICAL_REVIEW", oWorkflowPayload, oAssessmentHeader);
                            }

                            if (fnSuccess) {
                                fnSuccess();
                            }
                        }, fHandleError, false);
                    } else {
                        that.workBenchDataSource.createWorkflow([oWorkflowPayload], function () {
                            mWorkflow.setProperty("/dialog/isBusy", false);
                            
                            if (oAssessmentHeader.notifyByEmail) {
                                that.fnHandleSendEmail("RCM", "TECHNICAL_REVIEW", oWorkflowPayload, oAssessmentHeader);
                            }

                            if (fnSuccess) {
                                fnSuccess();
                            }
                        }, fHandleError, false);
                    }
                }, fHandleError, sEtag, false);
            };

            that.rcmDataSource.getRcmAssessmentDetails(sAssessmentId, function (oAssessmentHeader) {
                fnHandleComplete(oAssessmentHeader);
            }, fHandleError, false);

            mWorkflow.setProperty("/dialog/isBusy", true);

        },

