            //                     "deleted": false,
            //                     "uom_imperial": "",
            //                     "uom_metric": ""
            //                 };
            //                 if (aRecommendationRiskField[i].to_assessment_risk_data) {
            //                     // eslint-disable-next-line camelcase
            //                     oRiskFieldWithData.to_assessment_risk_data = {
            //                         "value": aRecommendationRiskField[i].to_assessment_risk_data.value,
            //                         "value_uom": aRecommendationRiskField[i].to_assessment_risk_data.value_uom,
            //                         "deleted": false
