            //         oApmRecoCreatePayload.sheMRAtDueDate = oAssessmentStrategy.sheMRAtDueDate ? oAssessmentStrategy.sheMRAtDueDate : "";
            //         oApmRecoCreatePayload.finMRAtDueDate = oAssessmentStrategy.finMRAtDueDate ? oAssessmentStrategy.finMRAtDueDate : "";
            //         oApmRecoCreatePayload.inspectionEffectivenessValue = oAssessmentStrategy.inspectionEffectivenessValue ? oAssessmentStrategy.inspectionEffectivenessValue : "";
